import type { DifferentialEvidence } from '../framework/contracts/index.js';
import type { Artifact } from '../framework/core/types.js';
import { createIRArtifact } from '../framework/ir/index.js';
import { applyNativePassSync, PassError } from '../framework/passes/index.js';
import { meaningGate } from './contract.js';
import { evaluate, type Inputs, type Precision, type BufferValue } from './evaluate.js';
import { adapter } from './ir.js';
import { selectFunction, type Module } from './model.js';
import { checkCudaLowering } from './cuda-contract.js';
import { runCudaBatch, type CudaInputs, type CudaResult } from './cuda-runtime.js';
import { emitCuda } from './cuda-source.js';
import { parse } from './parser.js';
import { inlinePass, splitPass } from './passes.js';

export interface TixProgram {
  readonly origin: Artifact<Module>;
  readonly current: Artifact<Module>;
}
export function compileTix(source: string): TixProgram {
  const origin = createIRArtifact(adapter, 'tix', parse(source));
  return { origin, current: origin };
}
export function runTix(
  program: TixProgram,
  fn: string,
  inputs: Inputs,
  options?: { precision?: Precision },
): BufferValue {
  return evaluate(selectFunction(program.current.value, fn), inputs, options?.precision ?? 'f32');
}
export function optimizeTix(program: TixProgram, passes: string[]) {
  const { origin } = program;
  let { current } = program;
  const steps = passes.map(pass => {
    const definition = pass === 'inline' ? inlinePass : pass === 'split-sum' ? splitPass : undefined;
    if (!definition) throw Error('Unknown pass ' + pass);
    try {
      const result = applyNativePassSync(
        definition,
        current,
        meaningGate(origin, pass === 'inline' ? 'exact' : 'tolerance'),
      );
      current = result.artifact;
      return { pass, accepted: true, changed: result.changed };
    } catch (error) {
      if (error instanceof PassError && error.code === 'contractRejected') {
        const evidence = error.evidence as DifferentialEvidence | undefined;
        return {
          pass,
          accepted: false,
          changed: false,
          reason: evidence?.counterexamples[0]?.reason ?? error.message,
        };
      }
      throw error;
    }
  });
  return { program: { origin, current }, steps };
}

export function cudaSource(program: TixProgram, fn: string): string {
  return emitCuda(selectFunction(program.current.value, fn));
}

export async function runTixCuda(
  program: TixProgram,
  fn: string,
  inputs: CudaInputs,
  options?: { host?: string },
): Promise<CudaResult> {
  const f = selectFunction(program.current.value, fn);
  const [result] = await runCudaBatch(emitCuda(f), f, [inputs], { host: options?.host });
  return result;
}

export function checkLowering(
  program: TixProgram,
  fn: string,
): Promise<{ accepted: boolean; relation: 'exact' | 'tolerance'; reason?: string }> {
  return checkCudaLowering(program.current, fn);
}

import { defineIR } from '../framework/contracts/index.js';
import { defineAdapter, type IREntity, type IRRelation } from '../framework/ir/index.js';
import { plain, visit, type Affine, type Axis, type Expr, type Fn, type Module } from './model.js';

function requireIR(condition: unknown, reason: string): asserts condition {
  if (!condition) throw Error(reason);
}
function same(a: unknown, b: unknown) {
  return JSON.stringify(a) === JSON.stringify(b);
}
function checkForm(a: Affine, names: Set<string>) {
  requireIR(
    Number.isSafeInteger(a.constant) && a.terms.every(([n, k]) => names.has(n) && Number.isSafeInteger(k)),
    'Invalid affine form',
  );
}
function validateFn(fn: Fn) {
  const shapes = new Set(fn.params.flatMap(p => p.shape.map(plain).filter((s): s is string => !!s)));
  const tensors = new Map<string, Affine[]>();
  const declare = (t: { name: string; shape: Affine[] }) => {
    requireIR(!tensors.has(t.name) && t.shape.length, 'Invalid tensor definition');
    for (const d of t.shape) {
      checkForm(d, shapes);
      requireIR(d.terms.length || d.constant >= 0, 'Negative dimension');
    }
    tensors.set(t.name, t.shape);
  };
  fn.params.forEach(declare);
  function bind(axes: Axis[], outer: Set<string>) {
    const scope = new Set(outer);
    requireIR(axes.length, 'Missing axes');
    for (const a of axes) {
      requireIR(!scope.has(a.id), 'Duplicate binder');
      const e = a.extent;
      checkForm(e.dim, shapes);
      requireIR(
        e.kind === 'dim' ||
          (e.kind === 'blocks' && ['ceil', 'floor'].includes(e.rounding)) ||
          (e.kind === 'tail' && scope.has(e.block)),
        'Invalid reduction bound',
      );
      scope.add(a.id);
    }
    return scope;
  }
  function expr(e: Expr, scope: Set<string>) {
    switch (e.kind) {
      case 'literal':
        requireIR(!Number.isNaN(Number(e.text)), 'Invalid literal');
        break;
      case 'shape':
        requireIR(shapes.has(e.name), 'Unknown shape');
        break;
      case 'load':
        requireIR(tensors.get(e.name)?.length === e.indices.length, 'Invalid tensor read');
        e.indices.forEach(a => checkForm(a, scope));
        break;
      case 'op':
        requireIR(
          (['neg', 'exp', 'log', 'tanh', 'sqrt'].includes(e.op) && e.args.length === 1) ||
            (['+', '-', '*', '/', 'min', 'max'].includes(e.op) && e.args.length === 2),
          'Invalid operation',
        );
        e.args.forEach(x => expr(x, scope));
        break;
      case 'reduce':
        requireIR(e.op === 'sum' || e.op === 'max', 'Invalid reduction');
        expr(e.body, bind(e.axes, scope));
        break;
      default:
        throw Error('Invalid expression');
    }
  }
  for (const s of fn.statements) {
    requireIR(
      s.axes.length === s.shape.length &&
        s.axes.every((a, i) => a.extent.kind === 'dim' && same(a.extent.dim, s.shape[i])),
      'Invalid result axes',
    );
    expr(s.expr, bind(s.axes, new Set()));
    declare(s);
  }
  requireIR(same(tensors.get(fn.result), fn.shape), 'Invalid result');
}
function validate(value: unknown) {
  const m = value as Module;
  requireIR(
    Array.isArray(m.functions) &&
      m.functions.length &&
      new Set(m.functions.map(f => f.name)).size === m.functions.length,
    'Invalid functions',
  );
  m.functions.forEach(validateFn);
}
export const TixIR = defineIR<Module>({
  id: 'tensor.tix',
  version: '1',
  description: 'Ordered tensor definitions with affine reads',
  validate,
});
function* entities(m: Module): Generator<IREntity> {
  for (const { name, statements, params, shape, result } of m.functions) {
    yield { id: name, kind: 'function', attributes: { shape, result } };
    for (const t of [...params, ...statements])
      yield { id: name + '/' + t.name, kind: 'tensor', attributes: { ...t } };
  }
}
function* relations(m: Module): Generator<IRRelation> {
  for (const f of m.functions) {
    let order = 0;
    for (const t of [...f.params, ...f.statements]) {
      const to = f.name + '/' + t.name;
      yield {
        id: 'contains/' + to,
        from: f.name,
        to,
        kind: 'contains',
        category: 'containment',
        order: order++,
      };
    }
    for (const s of f.statements) {
      const from = f.name + '/' + s.name;
      const reads = new Set<string>();
      visit(s.expr, e => {
        if (e.kind === 'load') reads.add(e.name);
      });
      for (const n of reads)
        yield {
          id: 'reads/' + from + '/' + n,
          from,
          to: f.name + '/' + n,
          kind: 'reads',
          category: 'dependency',
        };
    }
  }
}
export const adapter = defineAdapter<Module>({
  id: 'tensor.adapter',
  version: '1',
  description: 'Functions, tensor definitions and reads',
  kind: TixIR.id,
  schemaVersion: TixIR.version,
  validate,
  relationKinds: { contains: 'containment', reads: 'dependency' },
  entities,
  relations,
  resolve: (m, id) => [...entities(m)].find(e => e.id === id),
  describe: (_, id) => ({ label: id }),
});

// Affine forms use ordered terms so equivalent dimensions have the same artifact identity.
export interface Affine {
  constant: number;
  terms: [string, number][];
}
export const constant = (value: number): Affine => ({ constant: value, terms: [] });
export const variable = (name: string): Affine => ({ constant: 0, terms: [[name, 1]] });
export function add(a: Affine, b: Affine, scale = 1): Affine {
  const terms = new Map(a.terms);
  for (const [name, k] of b.terms) terms.set(name, (terms.get(name) ?? 0) + k * scale);
  const result = {
    constant: a.constant + b.constant * scale,
    terms: [...terms].filter(([, k]) => k !== 0).sort(([x], [y]) => (x < y ? -1 : 1)),
  };
  if (![result.constant, ...result.terms.map(([, k]) => k)].every(Number.isSafeInteger))
    throw Error('Affine integer overflow');
  return result;
}
export function substitute(a: Affine, bindings: Map<string, Affine>): Affine {
  return a.terms.reduce(
    (v, [name, k]) => add(v, bindings.get(name) ?? variable(name), k),
    constant(a.constant),
  );
}
export function value(a: Affine, env: Map<string, number>): number {
  return a.terms.reduce((v, [name, k]) => v + env.get(name)! * k, a.constant);
}
export function plain(a: Affine): string | undefined {
  return a.constant === 0 && a.terms.length === 1 && a.terms[0][1] === 1 ? a.terms[0][0] : undefined;
}
export type Extent =
  | { kind: 'dim'; dim: Affine }
  | { kind: 'blocks'; dim: Affine; rounding: 'ceil' | 'floor' }
  | { kind: 'tail'; dim: Affine; block: string };
export interface Axis {
  id: string;
  extent: Extent;
}
export type Op = '+' | '-' | '*' | '/' | 'neg' | 'exp' | 'log' | 'sqrt' | 'tanh' | 'max' | 'min';
export type Expr =
  | { kind: 'literal'; text: string }
  | { kind: 'shape'; name: string }
  | { kind: 'load'; name: string; indices: Affine[] }
  | { kind: 'op'; op: Op; args: Expr[] }
  | { kind: 'reduce'; op: 'sum' | 'max'; axes: Axis[]; body: Expr };
export interface Tensor {
  name: string;
  shape: Affine[];
}
export interface Statement extends Tensor {
  axes: Axis[];
  expr: Expr;
}
export interface Fn {
  name: string;
  params: Tensor[];
  statements: Statement[];
  result: string;
  shape: Affine[];
}
export interface Module {
  functions: Fn[];
}
export const width = 4;
export function mapExpr(e: Expr, f: (e: Expr) => Expr): Expr {
  if (e.kind === 'op') e = { ...e, args: e.args.map(x => mapExpr(x, f)) };
  if (e.kind === 'reduce') e = { ...e, body: mapExpr(e.body, f) };
  return f(e);
}
export function visit(e: Expr, f: (e: Expr) => void) {
  f(e);
  if (e.kind === 'op') e.args.forEach(x => visit(x, f));
  if (e.kind === 'reduce') visit(e.body, f);
}

export function selectFunction(module: Module, name: string): Fn {
  const fn = module.functions.find(f => f.name === name);
  if (!fn) throw Error('Unknown function ' + name);
  return fn;
}

import { plain, visit, width, type Affine, type Expr, type Fn, type Tensor } from './model.js';

const support = String.raw`
#include <cuda_runtime.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <memory>
#include <stdexcept>
#include <vector>

using I = int64_t;
using U = uint64_t;

static void check(cudaError_t status) {
  if (status != cudaSuccess) throw std::runtime_error(cudaGetErrorString(status));
}

__device__ static float minmax(float a, float b, bool maximum) {
  if (isnan(a) || isnan(b)) return __uint_as_float(0x7fc00000);
  if (a == b) {
    unsigned x = __float_as_uint(a), y = __float_as_uint(b);
    return __uint_as_float(maximum ? x & y : x | y);
  }
  return (maximum ? a > b : a < b) ? a : b;
}

struct DeviceBuffer {
  float* ptr = nullptr;
  U size;
  explicit DeviceBuffer(U n) : size(n) {
    if (size) check(cudaMalloc(&ptr, size * sizeof(float)));
  }
  ~DeviceBuffer() { if (ptr) cudaFree(ptr); }
  DeviceBuffer(const DeviceBuffer&) = delete;
  void upload(const float* src) const {
    if (size) check(cudaMemcpy(ptr, src, size * sizeof(float), cudaMemcpyHostToDevice));
  }
  void download(float* dst) const {
    if (size) check(cudaMemcpy(dst, ptr, size * sizeof(float), cudaMemcpyDeviceToHost));
  }
};

template <size_t N> static U elements(const std::array<I, N>& shape) {
  U n = 1;
  for (I extent : shape) n *= static_cast<U>(extent);
  return n;
}

template <class T> static void read(FILE* file, T* ptr, size_t count) {
  if (count && fread(ptr, sizeof(T), count, file) != count) throw std::runtime_error("short CUDA request");
}

template <class T> static void write(FILE* file, const T* ptr, size_t count) {
  if (count && fwrite(ptr, sizeof(T), count, file) != count) throw std::runtime_error("short CUDA response");
}

struct Event {
  cudaEvent_t handle;
  Event() { check(cudaEventCreate(&handle)); }
  ~Event() { cudaEventDestroy(handle); }
};

template <class Launch> static double time_kernels(const Launch& launch, bool benchmark) {
  Event start, stop;
  if (benchmark) {
    launch();
    check(cudaDeviceSynchronize());
  }
  std::array<float, 3> ms{};
  const int repeats = benchmark ? ms.size() : 1;
  for (int i = 0; i < repeats; ++i) {
    check(cudaEventRecord(start.handle));
    launch();
    check(cudaEventRecord(stop.handle));
    check(cudaEventSynchronize(stop.handle));
    check(cudaEventElapsedTime(&ms[i], start.handle, stop.handle));
  }
  if (benchmark) std::sort(ms.begin(), ms.end());
  return ms[repeats / 2];
}
`;

const main = String.raw`
int main(int argc, char** argv) {
  try {
    using File = std::unique_ptr<FILE, decltype(&fclose)>;
    File input(fopen("inputs.bin", "rb"), fclose);
    File output(fopen("out/results.bin", "wb"), fclose);
    if (!input || !output) throw std::runtime_error("cannot open CUDA request or response");
    const char magic[] = "TIXCUDA1";
    char header[8];
    read(input.get(), header, sizeof(header));
    if (memcmp(header, magic, sizeof(header))) throw std::runtime_error("bad CUDA request header");
    U count;
    read(input.get(), &count, 1);
    write(output.get(), magic, sizeof(header));
    write(output.get(), &count, 1);
    const bool benchmark = argc == 2 && strcmp(argv[1], "--benchmark") == 0;
    for (U i = 0; i < count; ++i) run_case(input.get(), output.get(), benchmark);
    if (fgetc(input.get()) != EOF || ferror(input.get())) throw std::runtime_error("trailing CUDA request data");
    if (fclose(output.release())) throw std::runtime_error("cannot close CUDA response");
    return 0;
  } catch (const std::exception& error) {
    fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
`;

function affine(a: Affine, name: (key: string) => string): string {
  const terms = a.terms.map(([key, coefficient]) =>
    coefficient === 1 ? name(key) : `${coefficient}LL * ${name(key)}`,
  );
  if (a.constant || !terms.length) terms.unshift(`${a.constant}LL`);
  return `(${terms.join(' + ')})`;
}

function literal(text: string): string {
  const bytes = new DataView(new ArrayBuffer(4));
  bytes.setFloat32(0, Number(text));
  return `__uint_as_float(0x${bytes.getUint32(0).toString(16)}u)`;
}

function emitKernel(
  statement: Fn['statements'][number],
  kernel: string,
  dimensions: ReadonlyMap<string, string>,
  tensors: ReadonlyMap<string, Tensor>,
  tensorName: (name: string) => string,
) {
  const reads = new Set<string>();
  visit(statement.expr, e => {
    if (e.kind === 'load') reads.add(e.name);
  });
  const args = [...dimensions.values(), ...Array.from(reads, tensorName), tensorName(statement.name)];
  const params = [
    ...Array.from(dimensions.values(), d => `I ${d}`),
    ...Array.from(reads, t => `const float* ${tensorName(t)}`),
    'float* result',
    'U count',
  ];
  const lines = [`__global__ void ${kernel}(${params.join(', ')}) {`];
  let indent = '  ',
    next = 0;
  const line = (code: string) => lines.push(indent + code);
  const dim = (a: Affine) => affine(a, n => dimensions.get(n)!);
  const indices = new Map<string, string>();
  const bind = (id: string) => {
    const name = `i${indices.size}`;
    indices.set(id, name);
    return name;
  };
  const index = (id: string) => indices.get(id)!;
  line('const U thread = static_cast<U>(blockIdx.x) * blockDim.x + threadIdx.x;');
  line('if (thread >= count) return;');
  line('U coordinate = thread;');
  for (let i = statement.axes.length - 1; i >= 0; --i) {
    const axis = bind(statement.axes[i].id);
    line(`const I ${axis} = coordinate % ${dim(statement.shape[i])};`);
    if (i > 0) line(`coordinate /= ${dim(statement.shape[i])};`);
  }

  const temporary = (code: string) => {
    const name = `v${next++}`;
    line(`float ${name} = ${code};`);
    return name;
  };

  function scalar(e: Expr): string {
    switch (e.kind) {
      case 'literal':
        return literal(e.text);
      case 'shape':
        return `__ll2float_rn(${dimensions.get(e.name)!})`;
      case 'load': {
        const shape = tensors.get(e.name)!.shape;
        const offset = e.indices.reduce(
          (prior, a, i) => (i ? `(${prior} * ${dim(shape[i])} + ${affine(a, index)})` : affine(a, index)),
          '',
        );
        return `${tensorName(e.name)}[${offset}]`;
      }
      case 'op': {
        const [a, b] = e.args.map(scalar);
        switch (e.op) {
          case '+':
            return temporary(`__fadd_rn(${a}, ${b})`);
          case '-':
            return temporary(`__fsub_rn(${a}, ${b})`);
          case '*':
            return temporary(`__fmul_rn(${a}, ${b})`);
          case '/':
            return temporary(`__fdiv_rn(${a}, ${b})`);
          case 'neg':
            return temporary(`-(${a})`);
          case 'sqrt':
            return temporary(`__fsqrt_rn(${a})`);
          case 'exp':
          case 'log':
          case 'tanh':
            return temporary(`__double2float_rn(${e.op}(static_cast<double>(${a})))`);
          case 'max':
          case 'min':
            return temporary(`minmax(${a}, ${b}, ${e.op === 'max'})`);
        }
      }
      case 'reduce': {
        const acc = temporary(e.op === 'sum' ? '0.0f' : '-INFINITY');
        for (const { id, extent } of e.axes) {
          const axis = bind(id),
            n = dim(extent.dim);
          let bound = n;
          if (extent.kind === 'blocks') {
            const tail = extent.rounding === 'ceil' ? ` + (${n} % ${width} != 0)` : '';
            bound = `${n} / ${width}${tail}`;
          }
          if (extent.kind === 'tail') {
            const remaining = `(${n} - ${width}LL * ${index(extent.block)})`;
            bound = `(${remaining} < ${width}LL ? ${remaining} : ${width}LL)`;
          }
          line(`const I end_${axis} = ${bound};`);
          line(`for (I ${axis} = 0; ${axis} < end_${axis}; ++${axis}) {`);
          indent += '  ';
        }
        const value = scalar(e.body);
        line(
          `${acc} = ${e.op === 'sum' ? `__fadd_rn(${acc}, ${value})` : `minmax(${acc}, ${value}, true)`};`,
        );
        for (const _axis of e.axes) {
          indent = indent.slice(2);
          line('}');
        }
        return acc;
      }
    }
  }
  const result = scalar(statement.expr);
  line(`result[thread] = ${result};`);
  lines.push('}');
  const count = `${tensorName(statement.name)}.size`;
  return {
    code: lines.join('\n'),
    preload: `  if (${count}) check(cudaFuncGetAttributes(&attributes, ${kernel}));`,
    hasWork: count,
    launch: `    if (${count}) {
      ${kernel}<<<(${count} - 1) / 256 + 1, 256>>>(${args.map((arg, i) => (i < dimensions.size ? arg : arg + '.ptr')).join(', ')}, ${count});
      check(cudaGetLastError());
    }`,
  };
}

export function emitCuda(fn: Fn): string {
  const all = [...fn.params, ...fn.statements];
  const tensors = new Map(all.map(t => [t.name, t]));
  const names = new Map(all.map((t, i) => [t.name, `t${i}`]));
  const name = (key: string) => names.get(key)!;
  const dims = new Map<string, string>(),
    bindings: string[] = [];
  for (const p of fn.params) {
    for (const [i, a] of p.shape.entries()) {
      const key = plain(a);
      if (key === undefined || dims.has(key)) continue;
      const d = `d${dims.size}`;
      dims.set(key, d);
      bindings.push(`  const I ${d} = shape_${name(p.name)}[${i}];`);
    }
  }
  const kernels = fn.statements.map((s, i) => emitKernel(s, `k${i}`, dims, tensors, name));
  const host = ['static void run_case(FILE* input, FILE* output, bool benchmark) {'];
  for (const p of fn.params) {
    const t = name(p.name);
    host.push(
      `  std::array<I, ${p.shape.length}> shape_${t};`,
      `  read(input, shape_${t}.data(), shape_${t}.size());`,
      `  std::vector<float> host_${t}(elements(shape_${t}));`,
      `  read(input, host_${t}.data(), host_${t}.size());`,
    );
  }
  const result = name(fn.result);
  let buffer = `host_${result}`;
  host.push('  double gpu_ms = 0;');
  if (kernels.length) {
    host.push(...bindings);
    for (const p of fn.params) {
      const t = name(p.name);
      host.push(`  DeviceBuffer ${t}(host_${t}.size());`, `  ${t}.upload(host_${t}.data());`);
    }
    for (const s of fn.statements) {
      const t = name(s.name);
      const dimsText = s.shape.map(a => affine(a, key => dims.get(key)!)).join(', ');
      host.push(
        `  const std::array<I, ${s.shape.length}> shape_${t}{${dimsText}};`,
        `  DeviceBuffer ${t}(elements(shape_${t}));`,
      );
    }
    host.push(
      '  cudaFuncAttributes attributes;',
      ...kernels.map(k => k.preload),
      `  if (${kernels.map(k => k.hasWork).join(' || ')}) gpu_ms = time_kernels([&] {`,
      ...kernels.map(k => k.launch),
      '  }, benchmark);',
    );
    if (fn.statements.some(s => s.name === fn.result)) {
      buffer = `host_${result}`;
      host.push(`  std::vector<float> ${buffer}(${result}.size);`, `  ${result}.download(${buffer}.data());`);
    }
  }
  host.push(
    `  write(output, shape_${result}.data(), shape_${result}.size());`,
    `  write(output, ${buffer}.data(), ${buffer}.size());`,
    '  write(output, &gpu_ms, 1);',
    '}',
  );
  return [support, ...kernels.map(k => k.code), host.join('\n'), main].join('\n\n');
}

import {
  AnalysisManager,
  ContractError,
  createArtifact,
  defineIR,
  defineTransformation,
  defineType,
  differential,
  type Decided,
  type DifferentialEvidence,
} from '../framework/contracts/index.js';
import type { Artifact } from '../framework/core/types.js';
import { coordinate, cudaCases, seed } from './contract.js';
import { runCudaBatch } from './cuda-runtime.js';
import { emitCuda } from './cuda-source.js';
import type { BufferValue } from './evaluate.js';
import { TixIR } from './ir.js';
import { selectFunction, type Module } from './model.js';

interface CudaUnit {
  fn: string;
  source: string;
}

const CudaIR = defineIR<CudaUnit>({
  id: 'tensor.cuda-source',
  version: '1',
  description: 'Standalone CUDA translation unit for a Tix function',
  validate(value) {
    const unit = value as Partial<CudaUnit> | null;
    if (typeof unit?.fn !== 'string' || !unit.fn || typeof unit.source !== 'string' || !unit.source)
      throw Error('Invalid CUDA translation unit');
  },
});
const FunctionName = defineType<string>({
  id: 'tensor.function-name',
  version: '1',
  description: 'Name of the Tix function to lower',
  validate(name) {
    if (typeof name !== 'string' || !name) throw Error('Invalid Tix function name');
  },
});

export function cudaArtifact(fn: string, source: string): Artifact<CudaUnit> {
  return createArtifact(CudaIR, 'tix-cuda/' + fn, { fn, source });
}

// The relation is exact: the lowered function must give the current revision's f32 meaning bit for bit, signed
// zeros and infinities included (IRWB-019 F17). The emitter makes that possible: explicit round-to-nearest
// arithmetic, so nothing contracts, and exp, log and tanh in double, rounded, which equal Math.fround(Math.exp(x))
// and so on for all 2^32 f32 inputs on the GB10 (IRWB-019 diary step 23). NaN is compared as a class, because the
// GPU and V8 produce different NaN words (sqrt of -2^-149: 0x7fffffff against 0xffc00000).
function compare(expected: BufferValue, got: BufferValue) {
  if (expected.shape.length !== got.shape.length || expected.shape.some((n, i) => n !== got.shape[i]))
    return { ok: false, reason: 'Output shape differs' };
  if (expected.data.length !== got.data.length) return { ok: false, reason: 'Output length differs' };
  const f32 = (d: ArrayLike<number>) => (d instanceof Float32Array ? d : Float32Array.from(d));
  const a = f32(expected.data),
    b = f32(got.data);
  const wa = new Uint32Array(a.buffer, a.byteOffset, a.length),
    wb = new Uint32Array(b.buffer, b.byteOffset, b.length);
  const hex = (w: number) => '0x' + w.toString(16).padStart(8, '0');
  for (let i = 0; i < a.length; i++) {
    if (wa[i] === wb[i] || (Number.isNaN(a[i]) && Number.isNaN(b[i]))) continue;
    const at = coordinate(expected.shape, i);
    return { ok: false, reason: `At [${at}], expected ${a[i]} (${hex(wa[i])}), got ${b[i]} (${hex(wb[i])})` };
  }
  return { ok: true };
}

type CudaSample = ReturnType<typeof cudaCases>[number];

export function createCudaLowering(profile: string, executeBatch: typeof runCudaBatch = runCudaBatch) {
  const inputs = { baseline: TixIR, fn: FunctionName };
  const outputs = { subject: CudaIR };
  const ports = { ...inputs, ...outputs };
  const invariant = differential<typeof ports, CudaSample, BufferValue>({
    id: 'tensor.cuda-meaning',
    version: '2',
    description:
      'Compare the lowered CUDA function to its current Tix f32 meaning, bit for bit (NaN as a class)',
    inputs: ports,
    baseline: 'baseline',
    subject: 'subject',
    // The recipe is shape-dependent and supplies its whole eligible case set.
    count: 1,
    seed,
    cases: ({ baseline, fn }, random) => {
      const samples = cudaCases(selectFunction(baseline.value, fn), random);
      if (!samples.length) throw Error('No eligible CUDA check cases for ' + fn);
      return samples;
    },
    run: (side, _artifact, sample) => {
      if (side === 'baseline') return sample.reference;
      throw Error('CUDA checks require the batch executor');
    },
    compare,
    describeCase: ({ fn, shapeValues, stream }) => ({ fn, shapeValues, stream, seed }),
    baselineKey: ({ baseline, fn }) => JSON.stringify([baseline.revision, fn]),
    subjectKey: (_artifact, _case, { subject }) => JSON.stringify([subject.revision, profile]),
    async decide({ baseline, fn, subject }, cases, todo) {
      if (subject.value.fn !== fn)
        return todo.map(() => ({ v: 'disagree', reason: 'CUDA function differs' }));
      const pending = todo.map(i => cases[i]);
      const results = await executeBatch(
        subject.value.source,
        selectFunction(baseline.value, fn),
        pending.map(c => c.inputs),
      );
      if (results.length !== pending.length) throw Error('Wrong CUDA response case count');
      return pending.map((sample, i): Decided => {
        const result = compare(sample.reference, results[i]);
        return result.ok ? { v: 'agree' } : { v: 'disagree', reason: result.reason! };
      });
    },
  });
  const pass = defineTransformation({
    id: 'tensor.lower-cuda',
    version: '1',
    description: 'Lower a Tix function to CUDA and check the candidate on the GPU',
    inputs,
    outputs,
    cache: 'never',
    ensures: [
      {
        invariant,
        bindings: {
          baseline: { from: 'inputs', port: 'baseline' },
          fn: { from: 'inputs', port: 'fn' },
          subject: { from: 'outputs', port: 'subject' },
        },
      },
    ],
    run(_ctx, { baseline, fn }) {
      return { outputs: { subject: cudaArtifact(fn, emitCuda(selectFunction(baseline.value, fn))) } };
    },
  });

  return async (baseline: Artifact<Module>, fn: string, candidate?: Artifact<CudaUnit>) => {
    const relation = 'exact' as const;
    const manager = new AnalysisManager();
    try {
      if (candidate) await manager.verifyTransformation({ baseline, fn }, { subject: candidate }, pass);
      else await manager.execute(pass, { baseline, fn });
      return { accepted: true, relation };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (error instanceof ContractError && error.code === 'postcondition') {
        const checks = manager.snapshot().executions.at(-1)?.checks;
        const evidence = checks?.find(check => check.phase === 'ensures')?.evidence as
          | DifferentialEvidence
          | undefined;
        const first = evidence?.counterexamples[0];
        const reason = first ? `${JSON.stringify(first.case)}: ${first.reason}` : message;
        return { accepted: false, relation, reason };
      }
      return { accepted: false, relation, reason: 'CUDA evidence unavailable: ' + message };
    }
  };
}

export const checkCudaLowering = createCudaLowering('cuda-remote:sm_121:-O3');

import { execFile } from 'node:child_process';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import { plain, value, type Fn } from './model.js';

export type CudaInputs = Record<string, { shape: number[]; data: Float32Array }>;
export interface CudaResult {
  shape: number[];
  data: Float32Array;
  gpuMs: number;
}

const magic = Buffer.from('TIXCUDA1');
const header = magic.length + 8;

function elements(shape: number[]): number {
  if (shape.some(dim => !Number.isSafeInteger(dim) || dim < 0)) throw Error('Invalid CUDA tensor shape');
  const count = shape.includes(0) ? 0 : shape.reduce((n, dim) => n * dim, 1);
  if (!Number.isSafeInteger(count)) throw Error('CUDA tensor size exceeds the host integer range');
  return count;
}

export function encodeCudaCases(fn: Fn, cases: readonly CudaInputs[]): Buffer {
  const tensors = cases.flatMap(inputs => {
    const dims = new Map<string, number>();
    const ordered = fn.params.map(p => {
      const tensor = Object.hasOwn(inputs, p.name) ? inputs[p.name] : undefined;
      if (!tensor || tensor.shape.length !== p.shape.length || elements(tensor.shape) !== tensor.data.length)
        throw Error('Invalid input shape or length for ' + p.name);
      for (const [i, d] of p.shape.entries()) {
        const key = plain(d);
        if (key === undefined) continue;
        if (dims.has(key) && dims.get(key) !== tensor.shape[i])
          throw Error('Inconsistent input extent ' + key);
        dims.set(key, tensor.shape[i]);
      }
      return tensor;
    });
    for (const [i, p] of fn.params.entries())
      if (p.shape.some((d, j) => value(d, dims) !== ordered[i].shape[j]))
        throw Error('Inconsistent affine shape for ' + p.name);
    return ordered;
  });
  const bytes = Buffer.allocUnsafe(
    header + tensors.reduce((n, t) => n + 8 * t.shape.length + 4 * t.data.length, 0),
  );
  magic.copy(bytes);
  let offset = bytes.writeBigUInt64LE(BigInt(cases.length), magic.length);
  for (const { shape, data } of tensors) {
    for (const dim of shape) offset = bytes.writeBigUInt64LE(BigInt(dim), offset);
    const words = new Uint32Array(data.buffer, data.byteOffset, data.length);
    for (const word of words) offset = bytes.writeUInt32LE(word, offset);
  }
  return bytes;
}

export function decodeCudaCases(bytes: Buffer, count: number, rank: number): CudaResult[] {
  if (bytes.length < header || !bytes.subarray(0, magic.length).equals(magic))
    throw Error('Invalid CUDA response header');
  if (bytes.readBigUInt64LE(magic.length) !== BigInt(count)) throw Error('Wrong CUDA response case count');
  const results: CudaResult[] = [];
  let offset = header;
  for (let c = 0; c < count; ++c) {
    if (rank * 8 > bytes.length - offset) throw Error('Short CUDA response shape');
    const shape = Array.from({ length: rank }, () => {
      const extent = Number(bytes.readBigUInt64LE(offset));
      offset += 8;
      return extent;
    });
    const n = elements(shape);
    if (n > (bytes.length - offset - 8) / 4) throw Error('Short CUDA response data');
    const words = new Uint32Array(n);
    for (let i = 0; i < n; i++) {
      words[i] = bytes.readUInt32LE(offset);
      offset += 4;
    }
    const gpuMs = bytes.readDoubleLE(offset);
    offset += 8;
    if (!Number.isFinite(gpuMs) || gpuMs < 0) throw Error('Invalid CUDA event time');
    results.push({ shape, data: new Float32Array(words.buffer), gpuMs });
  }
  if (offset !== bytes.length) throw Error('Trailing CUDA response bytes');
  return results;
}

const exec = promisify(execFile);
const runner = fileURLToPath(new URL('../../tools/cuda-remote.mjs', import.meta.url));
export async function runCudaBatch(
  source: string,
  fn: Fn,
  cases: readonly CudaInputs[],
  options?: { host?: string; benchmark?: boolean },
): Promise<CudaResult[]> {
  const request = encodeCudaCases(fn, cases);
  const dir = await mkdtemp(join(tmpdir(), 'irwb-tix-cuda-'));
  try {
    await Promise.all([writeFile(join(dir, 'main.cu'), source), writeFile(join(dir, 'inputs.bin'), request)]);
    const args = [runner, dir, '--runtime-input', 'inputs.bin'];
    if (options?.host !== undefined) args.push('--host', options.host);
    if (options?.benchmark) args.push('--timed', '--', '--benchmark');
    try {
      await exec(process.execPath, args);
    } catch (error) {
      const failure = error as Error & { stdout?: string; stderr?: string };
      let diagnostic = failure.stderr?.trim();
      try {
        const result = JSON.parse(failure.stdout ?? '');
        diagnostic ||= [result.stderr, result.stdout].filter(Boolean).join('\n').trim();
      } catch {
        // Copy and fetch failures can exit before the runner prints JSON.
      }
      throw new Error(diagnostic || failure.message, { cause: error });
    }
    return decodeCudaCases(await readFile(join(dir, 'out', 'results.bin')), cases.length, fn.shape.length);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

import {
  differential,
  differentialSpec,
  runDifferential,
  seededRandom,
  type CheckResult,
} from '../framework/contracts/index.js';
import type { Artifact } from '../framework/core/types.js';
import { evaluate, OutsideSample, size, type BufferValue } from './evaluate.js';
import type { CudaInputs } from './cuda-runtime.js';
import { TixIR } from './ir.js';
import { plain, value, type Fn, type Module } from './model.js';

type Relation = 'exact' | 'tolerance';
interface Sample {
  fn: string;
  shapeValues: number[];
  stream: string;
  inputs: CudaInputs;
  reference: BufferValue;
}
export const seed = 20;
const half = [1, 0, 0, 0, 2 ** -24, 2 ** -24, 2 ** -24];
function cases(fn: Fn, baseline: Fn, relation: Relation, random: () => number, cuda = false): Sample[] {
  const symbols = [
    ...new Set(fn.params.flatMap(p => p.shape.map(plain).filter((n): n is string => !!n))),
  ].sort();
  const seen = new Set<string>(),
    out: Sample[] = [];
  // 'mixed' gives every shape symbol a different size, so a pass that confuses two symbols changes some case
  // (a cycle of three sizes made symbols three apart equal in every case: IRWB-019 F21). The zero cases cover
  // empty extents.
  const distinct = [3, 5, 7, 2, 6, 4, 9, 8, 10, 11];
  const assignments = [1, 3, 4, 7, 'mixed'].map(n =>
    symbols.map((_, i) => (typeof n === 'number' ? n : (distinct[i] ?? i + 3))),
  );
  assignments.push(symbols.map(() => 0));
  for (const [zero] of symbols.entries()) assignments.push(symbols.map((_, i) => (i === zero ? 0 : 3)));
  for (const shapeValues of assignments) {
    const key = JSON.stringify(shapeValues);
    if (seen.has(key)) continue;
    seen.add(key);
    const dims = new Map(symbols.map((s, i) => [s, shapeValues[i]]));
    const shapes = fn.params.map(p => p.shape.map(d => value(d, dims)));
    if (shapes.some(s => s.some(x => x < 0) || size(s) > 4096)) continue;
    for (const stream of [
      'signed',
      'positive',
      'half-ulp',
      ...(relation === 'exact' || cuda ? ['zero'] : []),
    ]) {
      const inputs: CudaInputs = Object.create(null);
      fn.params.forEach((p, j) => {
        const shape = shapes[j];
        const data = Float32Array.from({ length: size(shape) }, (_, i) => {
          switch (stream) {
            case 'signed':
              return 2 * random() - 1;
            case 'positive':
              return 0.25 + 0.75 * random();
            case 'zero':
              return i % 2 ? -0 : 0;
            default:
              return half[i % half.length];
          }
        });
        inputs[p.name] = { shape, data };
      });
      try {
        const ref = evaluate(fn, inputs, relation === 'exact' ? 'f32' : 'f64', true);
        if (relation === 'tolerance' && !cuda && !ref.data.every(Number.isFinite)) continue;
        out.push({
          fn: fn.name,
          shapeValues,
          stream,
          inputs,
          reference: fn === baseline ? ref : evaluate(baseline, inputs, 'f32'),
        });
      } catch (error) {
        if (!(error instanceof OutsideSample)) throw error;
      }
    }
  }
  return out;
}
// The lowering's cases: references are the current revision's f32 meaning (IRWB-019 F17).
export function cudaCases(fn: Fn, random: () => number): Sample[] {
  return cases(fn, fn, 'exact', random, true);
}

export function coordinate(shape: number[], offset: number): number[] {
  const coord = shape.map(() => 0);
  for (let i = coord.length - 1; i >= 0; i--) {
    coord[i] = offset % shape[i];
    offset = Math.floor(offset / shape[i]);
  }
  return coord;
}

function compare(ref: BufferValue, got: BufferValue, relation: Relation) {
  if (JSON.stringify(ref.shape) !== JSON.stringify(got.shape))
    return { ok: false, reason: 'Output shape differs' };
  const words = (b: BufferValue) => new Uint32Array(b.data.buffer, b.data.byteOffset, b.data.length);
  const a = relation === 'exact' ? words(ref) : ref.data,
    b = relation === 'exact' ? words(got) : got.data;
  for (let i = 0; i < a.length; i++) {
    const allowed = 2e-6 + 2e-5 * Math.abs(a[i]);
    if (relation === 'exact' ? a[i] !== b[i] : !Number.isFinite(b[i]) || Math.abs(a[i] - b[i]) > allowed) {
      const coord = coordinate(ref.shape, i);
      return {
        ok: false,
        reason: `at [${coord}] expected ${a[i]}, got ${b[i]}, allowed ${relation === 'exact' ? 0 : allowed}`,
      };
    }
  }
  return { ok: true };
}
function signature(m: Module) {
  return JSON.stringify(m.functions.map(({ name, params, shape }) => ({ name, params, shape })));
}
export function meaningGate(origin: Artifact<Module>, relation: Relation) {
  return (before: Artifact<Module>, candidate: Artifact<Module>): CheckResult => {
    if (signature(origin.value) !== signature(candidate.value))
      return { ok: false, reason: 'Function signatures differ' };
    const baseline = relation === 'exact' ? before : origin;
    const samples: Sample[] = [];
    const random = seededRandom(seed);
    for (const [i, fn] of origin.value.functions.entries()) {
      const group = cases(fn, baseline.value.functions[i], relation, random);
      // empty-extent cases are compared, but only a case with every extent nonempty counts as coverage
      if (!group.some(c => c.shapeValues.every(v => v > 0)))
        return { ok: false, reason: 'No comparable case for ' + fn.name };
      samples.push(...group);
    }
    const ports = { baseline: TixIR, subject: TixIR };
    const invariant = differential<typeof ports, Sample, BufferValue>({
      id: 'tensor.meaning.' + relation,
      version: '1',
      description: 'Compare returned tensor on origin-derived cases',
      inputs: ports,
      baseline: 'baseline',
      subject: 'subject',
      seed,
      count: samples.length,
      cases: () => samples,
      run: (side, artifact, s) =>
        side === 'baseline'
          ? s.reference
          : evaluate(artifact.value.functions.find(f => f.name === s.fn)!, s.inputs, 'f32'),
      compare: (a, b) => compare(a, b, relation),
      describeCase: ({ fn, shapeValues, stream }) => ({ fn, shapeValues, stream, seed }),
    });
    const evidence = runDifferential(differentialSpec(invariant), { baseline, subject: candidate });
    return { ok: evidence.status === 'agree', reason: evidence.counterexamples[0]?.reason, evidence };
  };
}

import { plain, value, width, type Axis, type Expr, type Fn, type Op } from './model.js';
export interface BufferValue {
  shape: number[];
  data: Float32Array | Float64Array;
}
export type Inputs = Record<string, BufferValue>;
export type Precision = 'f32' | 'f64';
export const size = (shape: number[]) => shape.reduce((a, b) => a * b, 1);
const operations: Record<Op, (a: number, b: number) => number> = {
  '+': (a, b) => a + b,
  '-': (a, b) => a - b,
  '*': (a, b) => a * b,
  '/': (a, b) => a / b,
  neg: a => -a,
  exp: Math.exp,
  log: Math.log,
  sqrt: Math.sqrt,
  tanh: Math.tanh,
  max: Math.max,
  min: Math.min,
};
export class OutsideSample extends Error {}
// Limits apply only when selecting the contract's cases.
export function evaluate(fn: Fn, inputs: Inputs, precision: Precision, sampling = false): BufferValue {
  const ArrayType = precision === 'f32' ? Float32Array : Float64Array;
  const round = precision === 'f32' ? Math.fround : (x: number) => x;
  const shapes = new Map<string, number>(),
    indices = new Map<string, number>(),
    tensors = new Map<string, BufferValue>();
  let work = 0;
  function tick() {
    if (sampling && ++work > 1e6) throw new OutsideSample('Sample work limit');
  }
  for (const p of fn.params) {
    const input = inputs[p.name];
    p.shape.forEach((a, i) => {
      const n = plain(a);
      if (n) shapes.set(n, input.shape[i]);
    });
    tensors.set(p.name, { shape: input.shape, data: ArrayType.from(input.data) });
  }
  function loop(axes: Axis[], i: number, body: () => void) {
    if (i === axes.length) {
      body();
      return;
    }
    const { id, extent } = axes[i],
      dim = value(extent.dim, shapes);
    const n =
      extent.kind === 'blocks'
        ? Math[extent.rounding](dim / width)
        : extent.kind === 'tail'
          ? Math.min(width, dim - width * indices.get(extent.block)!)
          : dim;
    for (let j = 0; j < n; j++) {
      tick();
      indices.set(id, j);
      loop(axes, i + 1, body);
    }
  }
  function scalar(e: Expr): number {
    tick();
    switch (e.kind) {
      case 'literal':
        return round(Number(e.text));
      case 'shape':
        return round(shapes.get(e.name)!);
      case 'load': {
        const t = tensors.get(e.name)!;
        let offset = 0;
        for (let i = 0; i < e.indices.length; i++) {
          const ix = value(e.indices[i], indices);
          if (sampling && (ix < 0 || ix >= t.shape[i]))
            throw new OutsideSample('Sample outside address domain');
          offset = offset * t.shape[i] + ix;
        }
        return t.data[offset];
      }
      case 'op':
        return round(operations[e.op](scalar(e.args[0]), e.args.length === 2 ? scalar(e.args[1]) : 0));
      case 'reduce': {
        let acc = e.op === 'sum' ? 0 : -Infinity;
        loop(e.axes, 0, () => {
          const x = scalar(e.body);
          acc = round(e.op === 'sum' ? acc + x : Math.max(acc, x));
        });
        return acc;
      }
    }
  }
  for (const s of fn.statements) {
    const shape = s.shape.map(a => value(a, shapes));
    if (sampling && (shape.some(n => n < 0) || size(shape) > 4096))
      throw new OutsideSample('Sample shape limit');
    const data = new ArrayType(size(shape));
    let offset = 0;
    loop(s.axes, 0, () => {
      data[offset++] = scalar(s.expr);
    });
    tensors.set(s.name, { shape, data });
  }
  return tensors.get(fn.result)!;
}

import { definePass } from '../framework/passes/index.js';
import { adapter, TixIR } from './ir.js';
import {
  add,
  mapExpr,
  substitute,
  variable,
  visit,
  width,
  type Affine,
  type Expr,
  type Fn,
  type Module,
} from './model.js';

function replaceIndices(expr: Expr, bindings: Map<string, Affine>): Expr {
  return mapExpr(expr, e =>
    e.kind === 'load' ? { ...e, indices: e.indices.map(a => substitute(a, bindings)) } : e,
  );
}
function inline(fn: Fn): Fn {
  const statements = [...fn.statements];
  for (let i = 0; i < statements.length; i++) {
    const p = statements[i];
    if (p.name === fn.result) continue;
    let pointwise = true;
    visit(p.expr, e => {
      if (e.kind === 'reduce') pointwise = false;
    });
    if (!pointwise) continue;
    let uses = 0,
      consumer = -1;
    for (let j = i + 1; j < statements.length; j++)
      visit(statements[j].expr, e => {
        if (e.kind === 'load' && e.name === p.name) {
          uses++;
          consumer = j;
        }
      });
    if (uses !== 1) continue;
    const s = statements[consumer];
    statements[consumer] = {
      ...s,
      expr: mapExpr(s.expr, e => {
        if (e.kind !== 'load' || e.name !== p.name) return e;
        return replaceIndices(p.expr, new Map(p.axes.map((a, k) => [a.id, e.indices[k]])));
      }),
    };
    statements.splice(i--, 1);
  }
  return { ...fn, statements };
}
function split(fn: Fn): Fn {
  return {
    ...fn,
    statements: fn.statements.map(s => ({
      ...s,
      expr: mapExpr(s.expr, e => {
        if (e.kind !== 'reduce' || e.op !== 'sum' || e.axes.length !== 1) return e;
        const [{ id, extent }] = e.axes;
        if (extent.kind !== 'dim') return e;
        const { dim } = extent,
          block = id + '/block',
          lane = id + '/lane';
        const address = add(variable(lane), variable(block), width);
        const body = replaceIndices(e.body, new Map([[id, address]]));
        return {
          kind: 'reduce',
          op: 'sum',
          axes: [{ id: block, extent: { kind: 'blocks', dim, rounding: 'ceil' } }],
          body: {
            kind: 'reduce',
            op: 'sum',
            axes: [{ id: lane, extent: { kind: 'tail', dim, block } }],
            body,
          },
        };
      }),
    })),
  };
}
