    fail(token, (error as Error).message);
  }
  if ((!lo.terms.length && lo.constant < 0) || (!excess.terms.length && excess.constant >= 0))
    fail(token, 'Index outside axis');
}
export function parse(source: string): Module {
  return new Parser(lex(source)).program();
}
class Parser {
  private pos = 0;
  private nextId = 0;
  private tensors = new Map<string, Tensor>();
  private symbols = new Set<string>();
  private scope = new Map<string, Binder>();
  // Extents can be inferred by a later read in the same RHS.
  private accesses: Access[] = [];
  constructor(private tokens: Token[]) {}
  private get t() {
    return this.tokens[this.pos];
  }
  private take(s: string) {
    if (this.t.text !== s) return false;
    this.pos++;
    return true;
  }
  private expect(s: string) {
    if (!this.take(s)) fail(this.t, `Expected ${s}`);
  }
  private ident() {
    const t = this.t;
    if (!name.test(t.text)) fail(t, 'Expected name');
    this.pos++;
    return t;
  }
  private list<T>(read: () => T): T[] {
    const out = [read()];
    while (this.take(',')) out.push(read());
    return out;
  }
  program(): Module {
    const functions: Fn[] = [];
    do {
      const t = this.t;
      const fn = this.fn();
      if (functions.some(f => f.name === fn.name)) fail(t, 'Duplicate function');
      functions.push(fn);
    } while (this.t.text !== '<end>');
    return { functions };
  }
  private affine(index: boolean, min = 0): Affine {
    const start = this.t;
    let a: Affine;
    if (this.take('-')) a = add(constant(0), this.affine(index, 3), -1);
    else if (this.take('(')) {
      a = this.affine(index);
      this.expect(')');
    } else if (/^\d+$/.test(start.text)) {
      this.pos++;
      a = constant(Number(start.text));
      if (!Number.isSafeInteger(a.constant)) fail(start, 'Invalid integer');
    } else {
      const n = this.ident();
      const binder = this.scope.get(n.text);
      if (index && !binder) fail(n, 'Unknown index');
      a = variable(index ? binder!.id : n.text);
    }
    while (true) {
      const op = this.t,
        prec = op.text === '*' ? 2 : ['+', '-'].includes(op.text) ? 1 : 0;
      if (prec <= min) break;
      this.pos++;
      const b = this.affine(index, prec);
      try {
        if (op.text === '*') {
          if (a.terms.length && b.terms.length) fail(op, 'Non-affine product');
          a = a.terms.length ? add(constant(0), a, b.constant) : add(constant(0), b, a.constant);
        } else a = add(a, b, op.text === '+' ? 1 : -1);
      } catch (error) {
        fail(op, (error as Error).message);
      }
    }
    return a;
  }
  private type(input = false) {
    this.expect('f32');
    this.expect('[');
    const dims = this.list(() => {
      const t = this.t,
        d = this.affine(false);
      if (!d.terms.length && d.constant < 0) fail(t, 'Negative dimension');
      if (!input) for (const [n] of d.terms) if (!this.symbols.has(n)) fail(t, 'Unbound shape ' + n);
      return d;
    });
    this.expect(']');
    return dims;
  }
  private fn(): Fn {
    this.tensors.clear();
    this.symbols.clear();
    this.nextId = 0;
    this.expect('fn');
    const fn = this.ident().text;
    this.expect('(');
    const positions: Token[] = [];
    const params = this.list(() => {
      const n = this.ident();
      positions.push(n);
      if (this.tensors.has(n.text)) fail(n, 'Duplicate parameter');
      this.expect(':');
      const p = { name: n.text, shape: this.type(true) };
      this.tensors.set(p.name, p);
      return p;
    });
    for (const p of params)
      for (const d of p.shape) {
        const n = plain(d);
        if (n) this.symbols.add(n);
      }
    params.forEach((p, i) => {
      for (const d of p.shape)
        for (const [n] of d.terms) if (!this.symbols.has(n)) fail(positions[i], 'No input axis binds ' + n);
    });
    this.expect(')');
    this.expect(':');
    const shape = this.type();
    this.expect('{');
    const statements: Statement[] = [];
    while (!this.take('return')) statements.push(this.statement());
    const result = this.ident(),
      tensor = this.tensors.get(result.text);
    if (!tensor || JSON.stringify(tensor.shape) !== JSON.stringify(shape))
      fail(result, 'Invalid return tensor or shape');
    this.expect(';');
    this.expect('}');
    return { name: fn, params, statements, result: result.text, shape };
  }
  private binders() {
    const seen = new Set<string>();
    return this.list(() => {
      const token = this.ident();
      if (seen.has(token.text)) fail(token, 'Duplicate binder');
      seen.add(token.text);
      const b: Binder = { token, id: 'i' + this.nextId++ };
      this.scope.set(token.text, b);
      return b;
    });
  }
  private axes(binders: Binder[]): Axis[] {
    return binders.map(b => ({
      id: b.id,
      extent: { kind: 'dim', dim: b.dim ?? fail(b.token, 'Cannot infer extent') },
    }));
  }
  private statement(): Statement {
    this.scope.clear();
    this.accesses = [];
    const t = this.ident();
    if (this.tensors.has(t.text)) fail(t, 'Tensor already assigned');
    this.expect('[');
    const binders = this.binders();
    this.expect(']');
    if (this.take(':')) {
      const dims = this.type();
      if (dims.length !== binders.length) fail(t, 'Declared rank mismatch');
      binders.forEach((b, i) => (b.dim = dims[i]));
    }
    this.expect('=');
    const expr = this.expr();
    this.expect(';');
    const axes = this.axes(binders),
      shape = binders.map(b => b.dim!);
    this.accesses.forEach(checkBounds);
    const s = { name: t.text, shape, axes, expr };
    this.tensors.set(s.name, s);
    return s;
  }
  private expr(min = 0): Expr {
    let e = this.primary();
    while (true) {
      const op = this.t.text,
        prec = ['+', '-'].includes(op) ? 1 : ['*', '/'].includes(op) ? 2 : 0;
      if (prec <= min) return e;
      this.pos++;
      e = { kind: 'op', op: op as Op, args: [e, this.expr(prec)] };
    }
  }
  private maxBinderList() {
    let i = this.pos,
      names: string[] = [];
    while (name.test(this.tokens[i].text)) {
      names.push(this.tokens[i++].text);
      if (this.tokens[i].text !== ',') break;
      i++;
    }
    if (this.tokens[i].text !== ')') return false;
    const next = this.tokens[i + 1]?.text ?? '';
    return (
      (next === '(' || next === '-' || name.test(next) || number.test(next)) &&
      !(next === '-' && names.length === 2 && names.every(n => this.symbols.has(n)))
    );
  }
  private primary(): Expr {
    const t = this.t;
    if (this.take('-')) return { kind: 'op', op: 'neg', args: [this.expr(2)] };
    if (this.take('(')) {
      const e = this.expr();
      this.expect(')');
      return e;
    }
    if (number.test(t.text)) {
      this.pos++;
      return { kind: 'literal', text: t.text };
    }
    const n = this.ident().text;
    if (this.take('[')) {
      const tensor = this.tensors.get(n);
      if (!tensor) fail(t, 'Unknown tensor ' + n);
      let axis = 0;
      const indices = this.list(() => {
        const start = this.pos,
          tok = this.t,
          a = this.affine(true);
        const d = tensor.shape[axis++];
        if (!d) fail(tok, 'Too many axes');
        if (this.pos === start + 1 && name.test(tok.text)) {
          const b = this.scope.get(tok.text)!;
          if (b.dim && JSON.stringify(b.dim) !== JSON.stringify(d)) fail(tok, 'Inconsistent extent');
          b.dim = d;
        }
        const binders = new Map([...this.scope.values()].map(b => [b.id, b]));
        this.accesses.push({ index: a, extent: d, token: tok, binders });
        return a;
      });
      this.expect(']');
      if (indices.length !== tensor.shape.length) fail(t, 'Wrong reference rank');
      return { kind: 'load', name: n, indices };
    }
    if (this.take('(')) {
      if (n === 'sum' || (n === 'max' && this.maxBinderList())) {
        const outer = this.scope;
        this.scope = new Map(outer);
        const binders = this.binders();
        this.expect(')');
        const body = this.expr(),
          axes = this.axes(binders);
        this.scope = outer;
        return { kind: 'reduce', op: n, axes, body };
      }
      const args = this.list(() => this.expr());
      this.expect(')');
      const arity = ['exp', 'log', 'sqrt', 'tanh'].includes(n) ? 1 : ['max', 'min'].includes(n) ? 2 : 0;
      if (!arity || args.length !== arity) fail(t, 'Invalid intrinsic call');
      return { kind: 'op', op: n as Op, args };
    }
    if (!this.symbols.has(n)) fail(t, 'Unknown shape ' + n);
    return { kind: 'shape', name: n };
  }
}

// Run from the worktree root after building. Each line is one measured workload.
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

const root = pathToFileURL(process.cwd() + '/');
const { compileTix, cudaSource, runTix } = await import(new URL('dist/tensor/index.js', root));
const { runCudaBatch } = await import(new URL('dist/tensor/cuda-runtime.js', root));
const { value } = await import(new URL('dist/tensor/model.js', root));
const { seededRandom } = await import(new URL('dist/framework/contracts/index.js', root));

const sizes = {
  matmul: { M: 512, K: 512, N: 512 },
  softmax: { N: 4096, C: 1024 },
  layernorm: { N: 4096, D: 1024 },
  attention: { Q: 1024, K: 1024, D: 64, V: 64 },
  mlp: { N: 1024, D: 256, H: 1024, O: 256 },
  conv2d: { N: 8, C: 16, H: 64, W: 64, O: 32 },
};

const [mode, ...names] = process.argv.slice(2);
if (!['cpu', 'gpu'].includes(mode))
  throw Error('Usage: node <ticket>/scripts/03-benchmark-cuda.mjs cpu|gpu [names...]');
for (const name of names.length ? names : Object.keys(sizes)) {
  if (!Object.hasOwn(sizes, name)) throw Error('Unknown corpus function ' + name);
  const program = compileTix(await readFile(new URL(`corpus/tensor/${name}/main.tix`, root), 'utf8'));
  const fn = program.current.value.functions.find(f => f.name === name);
  const dims = new Map(Object.entries(sizes[name]));
  const random = seededRandom(20);
  const inputs = Object.fromEntries(
    fn.params.map(p => {
      const shape = p.shape.map(d => value(d, dims));
      const data = Float32Array.from({ length: shape.reduce((n, dim) => n * dim, 1) }, () =>
        name === 'layernorm' && p.name === 'eps' ? 1e-5 : 0.2 * random() - 0.1,
      );
      return [p.name, { shape, data }];
    }),
  );
  let result, ms;
  if (mode === 'cpu') {
    const start = performance.now();
    result = runTix(program, name, inputs);
    ms = performance.now() - start;
  } else {
    [result] = await runCudaBatch(cudaSource(program, name), fn, [inputs], { benchmark: true });
    ms = result.gpuMs;
  }
  const { data, shape } = result;
  const outputSha256 = createHash('sha256')
    .update(Buffer.from(data.buffer, data.byteOffset, data.byteLength))
    .digest('hex');
  console.log(JSON.stringify({ name, mode, ms, shape, outputSha256 }));
}

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import {
  checkLowering,
  compileTix,
  cudaSource,
  optimizeTix,
  runTix,
  runTixCuda,
} from '../../dist/tensor/index.js';
import { checkCudaLowering, cudaArtifact } from '../../dist/tensor/cuda-contract.js';

const buf = (shape, data) => ({ shape, data: Float32Array.from(data) });
const words = ({ data }) => new Uint32Array(data.buffer, data.byteOffset, data.length);

for (const name of ['matmul', 'softmax', 'layernorm', 'attention', 'mlp', 'conv2d']) {
  test('GB10 checks ' + name + ' before and after optimization', async () => {
    const source = await readFile(
      new URL('../../corpus/tensor/' + name + '/main.tix', import.meta.url),
      'utf8',
    );
    const program = compileTix(source);
    const optimized = optimizeTix(program, ['inline', 'split-sum']);
    assert.ok(optimized.steps.every(s => s.accepted));
    for (const revision of [program, optimized.program]) {
      const verdict = await checkLowering(revision, name);
      assert.equal(verdict.accepted, true, verdict.reason);
      assert.equal(verdict.relation, 'exact');
    }
  });
}

test('GB10 preserves split rounding and a partial final block', async () => {
  const p = compileTix('fn f(x:f32[N,K]):f32[N] { y[i] = sum(k) x[i,k]; return y; }');
  const { program, steps } = optimizeTix(p, ['split-sum']);
  assert.equal(steps[0].accepted, true);
  assert.notEqual(program.current.revision, p.current.revision);
  const inputs = { x: buf([1, 7], [1, 0, 0, 0, 2 ** -24, 2 ** -24, 2 ** -24]) };
  const reference = runTix(program, 'f', inputs);
  assert.equal(reference.data[0], 1 + 2 ** -22);
  const result = await runTixCuda(program, 'f', inputs);
  assert.deepEqual(result.shape, [1]);
  assert.deepEqual(words(result), words(reference));
  assert.ok(Number.isFinite(result.gpuMs) && result.gpuMs >= 0);

  const source = cudaSource(program, 'f');
  const mutant = source.replace(' + ((d1) % 4 != 0)', '');
  assert.notEqual(mutant, source);
  assert.equal((await checkLowering(program, 'f')).accepted, true);
  const verdict = await checkCudaLowering(program.current, 'f', cudaArtifact('f', mutant));
  assert.equal(verdict.accepted, false);
  assert.match(verdict.reason, /At \[.*\], expected/);
});

test('GB10 checks composed inline addresses and rejects a valid index mutant', async () => {
  const p = compileTix('fn f(x:f32[N,N]):f32[N,N] { z[i,j]=x[i,j]*2; y[i,j]=z[j,i]+1; return y; }');
  const { program } = optimizeTix(p, ['inline']);
  assert.notEqual(p.current.revision, program.current.revision);
  const x = { x: buf([2, 2], [1, 2, 3, 4]) };
  assert.deepEqual((await runTixCuda(program, 'f', x)).data, Float32Array.of(3, 7, 5, 9));

  const source = cudaSource(program, 'f');
  const mutant = source.replace('t0[((i0) * (d0) + (i1))]', 't0[((i1) * (d0) + (i0))]');
  assert.notEqual(mutant, source);
  const verdict = await checkCudaLowering(program.current, 'f', cudaArtifact('f', mutant));
  assert.equal(verdict.accepted, false);
  assert.match(verdict.reason, /At \[.*\], expected/);
});

test('GB10 handles shadowing, empty reductions and outputs, intrinsic edges, and direct returns', async () => {
  const program = compileTix(`
    fn shadow(x:f32[N,K], z:f32[N,L]):f32[N] { y[i] = sum(j) x[i,j] + sum(j) z[i,j]; return y; }
    fn empty(x:f32[N,K]):f32[N,2] {
      s[i] = sum(k) x[i,k]; m[i] = max(k) x[i,k];
      y[i,j]:f32[N,2] = max(s[i], m[i]) + (log(1) * 0);
      return y;
    }
    fn intrinsic(x:f32[N]):f32[N] { y[i]=min(sqrt(x[i]), 0); return y; }
    fn direct(x:f32[N]):f32[N] { return x; }
  `);
  const cases = [
    ['shadow', { x: buf([1, 2], [1, 2]), z: buf([1, 3], [4, 5, 6]) }, [33]],
    ['empty', { x: buf([3, 0], []) }, [0, 0, 0, 0, 0, 0]],
    ['empty', { x: buf([0, 3], []) }, []],
    ['intrinsic', { x: buf([3], [-1, -0, 2]) }, [NaN, -0, 0]],
    ['direct', { x: buf([1], [-0]) }, [-0]],
  ];
  for (const [name, inputs, expected] of cases) {
    const result = await runTixCuda(program, name, inputs);
    assert.deepEqual([...result.data], expected);
    assert.deepEqual(result.shape, runTix(program, name, inputs).shape);
    if (name === 'direct' || !expected.length) assert.equal(result.gpuMs, 0);
  }
  const max = compileTix('fn f(x:f32[N,K]):f32[N] { y[i] = max(k) x[i,k]; return y; }');
  assert.deepEqual(
    (await runTixCuda(max, 'f', { x: buf([2, 0], []) })).data,
    Float32Array.of(-Infinity, -Infinity),
  );
});

test('remote runner links repeated libraries and keys the build by their order', async () => {
  const tool = fileURLToPath(new URL('../../tools/cuda-remote.mjs', import.meta.url));
  // a 2x2 cublasSgemm checked against a CPU product (from IRWB-024's probe, scripts/01-cublas-product)
  const dir = fileURLToPath(new URL('./fixtures/cublas-product/', import.meta.url));
  async function run(first, second) {
    const { stdout } = await promisify(execFile)(process.execPath, [
      tool,
      dir,
      '--link',
      first,
      '--link',
      second,
    ]);
    const result = JSON.parse(stdout);
    assert.deepEqual(JSON.parse(result.stdout), [
      [19, 22],
      [43, 50],
    ]);
    return result.hash;
  }
  assert.notEqual(await run('m', 'cublas'), await run('cublas', 'm'));
});

test('remote runner shares a compile across isolated jobs and invalidates on build input changes', async () => {
  const tool = fileURLToPath(new URL('../../tools/cuda-remote.mjs', import.meta.url));
  const exec = promisify(execFile);
  const dirs = await Promise.all(['A', 'B'].map(() => mkdtemp(join(tmpdir(), 'irwb-cuda-runner-test-'))));
  const source = `// ${randomUUID()}
#include <cstdio>
#include "header.h"
int main() {
  FILE* in = fopen("input.txt", "r");
  FILE* out = fopen("out/answer.txt", "w");
  fputc(fgetc(in), out);
  fputc(EXTRA, out);
  fclose(in);
  return fclose(out);
}
`;
  try {
    await Promise.all(
      dirs.map(async (dir, i) => {
        await writeFile(join(dir, 'main.cu'), source);
        await writeFile(join(dir, 'header.h'), "#define EXTRA '1'\n");
        await writeFile(join(dir, 'input.txt'), i ? 'B' : 'A');
      }),
    );
    async function run(dir) {
      const { stdout } = await exec(process.execPath, [tool, dir, '--runtime-input', 'input.txt']);
      return { ...JSON.parse(stdout), answer: await readFile(join(dir, 'out', 'answer.txt'), 'utf8') };
    }
    const [a, b] = await Promise.all(dirs.map(run));
    assert.equal(a.hash, b.hash);
    assert.deepEqual([a.compiled, b.compiled].sort(), [false, true]);
    assert.deepEqual([a.answer, b.answer], ['A1', 'B1']);
    await writeFile(join(dirs[0], 'header.h'), "#define EXTRA '2'\n");
    const changed = await run(dirs[0]);
    assert.equal(changed.compiled, true);
    assert.notEqual(changed.hash, a.hash);
    assert.equal(changed.answer, 'A2');
  } finally {
    await Promise.all(dirs.map(dir => rm(dir, { recursive: true, force: true })));
  }
});
